        /// <summary>
        ///     Get the visit list based on some criteria
        /// </summary>
        /// <param name="employeeID">Employee ID</param>
        /// <param name="dateFrom">Date the result is filtered from</param>
        /// <param name="dateTo">Date the result is filtered to</param>
        /// <returns>Patient visit list</returns>
        public IList<MEPatientVisitsInfo> GetPatientVisitList(int? employeeID, DateTime? dateFrom, DateTime? dateTo)
        {
            var ds = dal.GetDataSet("MEPatientVisits_GetPatientVisitList", employeeID, dateFrom, dateTo);
            IList<MEPatientVisitsInfo> patientVisitList = new List<MEPatientVisitsInfo>();
            if (ds.Tables.Count > 0)
            {
                for (var i = 0; i < ds.Tables[0].Rows.Count; i++)
                {
                    var objPatientVisitsInfo = (MEPatientVisitsInfo) GetObjectFromDataRow(ds.Tables[0].Rows[i]);
                    objPatientVisitsInfo.CompleteServiceDisplayedText = string.Format("{0} / {1}",
                        objPatientVisitsInfo.CompleteServiceCount, objPatientVisitsInfo.TotalServiceCount);
                    if (objPatientVisitsInfo.TotalServiceCount == 0)
                        objPatientVisitsInfo.CompleteServiceDisplayedText = string.Empty;
                    patientVisitList.Add(objPatientVisitsInfo);
                }

                for (var i = 0; i < patientVisitList.Count; i++)
                    if (patientVisitList[i].MEPatientVisitID > 0)
                        for (var j = 0; j < patientVisitList.Count; j++)
                            if (patientVisitList[j].MEPatientVisitID == 0 &&
                                patientVisitList[j].METimeFrameStartTime == patientVisitList[i].METimeFrameStartTime)
                            {
                                patientVisitList.RemoveAt(j);
                                if (j <= i)
                                    i--;
                                j--;
                            }
            }
            return patientVisitList;
        }

