        /// <summary>
        ///     Get the entire status of a visit
        /// </summary>
        /// <param name="patientVisitID">Patient visit id</param>
        /// <returns>Status list of all services of the visit</returns>
        public List<ServiceStatusInfo> GetVisitStatus(int patientVisitID)
        {
            var serviceStatusList = new List<ServiceStatusInfo>();
            //Get vital signs status
            var temp = GetVitalSignsStatus(patientVisitID);
            foreach (var objServiceStatusInfo in temp)
                serviceStatusList.Add(objServiceStatusInfo);

            //Get progress note status
            temp = GetProgressNoteStatus(patientVisitID);
            foreach (var objServiceStatusInfo in temp)
                serviceStatusList.Add(objServiceStatusInfo);

            //Get order item status
            temp = GetOrderItemStatus(patientVisitID);
            foreach (var objServiceStatusInfo in temp)
                serviceStatusList.Add(objServiceStatusInfo);

            //Get medication status
            temp = GetMedicationStatus(patientVisitID);
            foreach (var objServiceStatusInfo in temp)
                serviceStatusList.Add(objServiceStatusInfo);

            return serviceStatusList;
        }

