        #region LabTable

        /// <summary>
        ///     Build data set follow construct of lab table of a patient
        /// </summary>
        /// <param name="patientID">Patient id</param>
        /// <param name="labID">Lab id</param>
        /// <returns>Data table of labs of the patient</returns>
        public DataSet GetAllDataForLabTable(int patientID, int labID)
        {
            var ds = dal.GetDataSet("MEPatientVisit_GetDataForLabTable", patientID, labID);
            var table = ds.Tables[0];

            //DDCan [Show Visit Lab ID]
            //var dateRows = table.Select().Select(p => new { Date = p["MEVisitLabDate"] }).Distinct();
            //DataTable dbLabTable = new DataTable();
            //dbLabTable.Columns.Add(EntityLocalizedResources.ParamName, typeof(string));
            //foreach (var row in dateRows)
            //{
            //    dbLabTable.Columns.Add(((DateTime)row.Date).ToString("dd/MM/yyyy HH:mm"), typeof(string));
            //}
            var dbLabTable = new DataTable();
            dbLabTable.Columns.Add(EntityLocalizedResources.ParamName, typeof(string));

            var dataRows =
                table.Select().Select(row => new {ID = row["MEVisitLabID"], Date = row["MEVisitLabDate"]}).Distinct();
            foreach (var row in dataRows)
                dbLabTable.Columns.Add(
                    EntityLocalizedResources.LabRequestNo + ": " + Convert.ToInt32(row.ID).ToString("000000") + "\n\n" +
                    EntityLocalizedResources.LabRequestDate + ": " + ((DateTime) row.Date).ToString("dd/MM/yyyy HH:mm"),
                    typeof(string));

            var paramNameRows = table.Select().Select(p => new {Name = p["MEVisitLabParamName"]}).Distinct();
            List<string> values;
            foreach (var row in paramNameRows)
            {
                //dbLabTable.Rows.Add(ConstructDataRow((string)row.Name, table));
                values = new List<string>();
                values.Add((string) row.Name);
                foreach (var row1 in dataRows)
                {
                    var value = ConstructDataRow((string) row.Name, Convert.ToInt32(row1.ID), (DateTime) row1.Date,
                        table);
                    values.Add(value);
                }
                dbLabTable.Rows.Add(values.ToArray());
            }

            var dsLabTable = new DataSet();
            dsLabTable.Tables.Add(dbLabTable);
            return dsLabTable;
        }

        private string ConstructDataRow(string name, int visitLabID, DateTime visitLabDate, DataTable table)
        {
            var tmp = table.Select()
                .Where(p => (string) p["MEVisitLabParamName"] == name &&
                            (DateTime) p["MEVisitLabDate"] == visitLabDate &&
                            (int) p["MEVisitLabID"] == visitLabID)
                //.OrderByDescending(p => p["MEVisitLabDate"])
                .Select(c => c["MEVisitLabParamValue"])
                .FirstOrDefault();
            //object[] rs = new object[tmp.Count() + 1];
            //rs[0] = name;
            //int index = 1;
            //foreach (var item in tmp)
            //{
            //    rs[index++] = item;
            //}
            //return rs;

            return tmp == null ? string.Empty : tmp.ToString();
        }

